def project(xyz,c):
    p=xyz-c["center"]
    x=((p@c["right"])/c["span"][0]+.5)*c["width"]
    y=(.5-(p@c["up"])/c["span"][1])*c["height"]
    z=p@c["view"]
    return np.c_[x,y,z].astype(np.float32)

